export declare const LOBBY_HERO_CSS = "\n.lobby-hero{position:absolute;inset:0;container-type:size;display:flex;flex-direction:column;\n align-items:center;justify-content:center;gap:clamp(6px,2.4cqh,14px);pointer-events:none;\n --lobby-hero-size:min(calc(100cqw - 32px),calc(100cqh - 72px),200px)}\n.lobby-hero-art{width:min(100cqw,100cqh,360px);height:min(100cqw,100cqh,360px);object-fit:contain}\n.lobby-hero-card{box-sizing:border-box;width:var(--lobby-hero-size);height:var(--lobby-hero-size);\n border-radius:50%;display:flex;align-items:center;justify-content:center;\n background:radial-gradient(circle at 50% 35%,var(--mp-raised,#2A2D5C),var(--mp-surface,#1B1E44));\n border:3px solid var(--mp-violet,#7E80FF);\n box-shadow:0 20px 40px rgba(0,0,0,.35),inset 0 -10px 0 rgba(0,0,0,.18)}\n.lobby-hero-number{font-family:var(--mp-font-display);font-weight:800;line-height:1;\n font-size:calc(var(--lobby-hero-size) * .46);color:var(--mp-text,#fff);\n text-shadow:0 4px 0 rgba(0,0,0,.25)}\n.lobby-hero-label{font-family:var(--mp-font-display);font-weight:700;font-size:18px;\n color:var(--mp-text-2,#C9CCF2)}\n.lobby-hero-dots{display:flex;gap:8px;align-items:center}\n.lobby-hero-dot{width:12px;height:12px;border-radius:6px;background:rgba(255,255,255,.18)}\n.lobby-hero-dot[data-done=true]{background:var(--mp-mint,#4CC98A)}\n";
